package ru.mcsa.bukkit;
import java.util.*;import org.bukkit.NamespacedKey;import org.bukkit.persistence.*;
public class DataContainer implements PersistentDataContainer {
 protected void changed(){}
 private final Map<String,Object> values=new LinkedHashMap<>();
 private static String kind(PersistentDataType<?,?> type){if(type instanceof ListPersistentDataType)return "list:"+kind(((ListPersistentDataType<?,?>)type).elementType());Class<?> primitive=type.getPrimitiveType();if(primitive==Byte.class)return "byte";if(primitive==Integer.class)return "int";if(primitive==Long.class)return "long";if(primitive==Double.class)return "double";if(primitive==String.class)return "string";throw new IllegalArgumentException("Неподдерживаемый тип PDC");}
 private static int size(Object value){return Yaml.write(value).getBytes(java.nio.charset.StandardCharsets.UTF_8).length;}
 private static boolean validValue(Object value,String kind,int depth){if(depth>8)return false;if(kind.startsWith("list:")){if(!(value instanceof List)||((List<?>)value).size()>1024)return false;for(Object item:(List<?>)value)if(!validValue(item,kind.substring(5),depth+1))return false;return true;}if(kind.equals("string"))return value instanceof String;if(!(value instanceof Number))return false;Number number=(Number)value;if(kind.equals("double"))return Double.isFinite(number.doubleValue());if(!(value instanceof Byte||value instanceof Integer||value instanceof Long))return false;long n=number.longValue();switch(kind){case "byte":return n>=-128&&n<=127;case "int":return n>=Integer.MIN_VALUE&&n<=Integer.MAX_VALUE;case "long":return true;default:return false;}}
 private static Object copy(Object value){if(value instanceof List){List<Object> out=new ArrayList<>();for(Object item:(List<?>)value)out.add(copy(item));return out;}return value;}
 public <P,C>void set(NamespacedKey key,PersistentDataType<P,C> type,C value){Objects.requireNonNull(key);Objects.requireNonNull(type);Objects.requireNonNull(value);String kind=kind(type);Object primitive=type.toPrimitive(value,getAdapterContext());if(!type.getPrimitiveType().isInstance(primitive)||!validValue(primitive,kind,0))throw new IllegalArgumentException("Неверный примитив PDC");Map<String,Object> entry=new LinkedHashMap<>();entry.put("type",kind);entry.put("value",copy(primitive));Object old=values.put(key.toString(),entry);if(values.size()>256||size(values)>16384){if(old==null)values.remove(key.toString());else values.put(key.toString(),old);throw new IllegalArgumentException("Лимит PDC: 256 ключей / 16 КиБ");}changed();}
 @SuppressWarnings("unchecked") public <P,C>C get(NamespacedKey key,PersistentDataType<P,C> type){Object entry=values.get(Objects.requireNonNull(key).toString());if(entry==null)return null;Map<?,?> map=(Map<?,?>)entry;if(!kind(type).equals(map.get("type")))return null;Object value=convert(map.get("value"),kind(type));return type.fromPrimitive((P)copy(value),getAdapterContext());}
 private static Object convert(Object value,String kind){if(kind.startsWith("list:")){List<Object> out=new ArrayList<>();for(Object item:(List<?>)value)out.add(convert(item,kind.substring(5)));return out;}if(value instanceof Number){Number n=(Number)value;switch(kind){case "byte":return n.byteValue();case "int":return n.intValue();case "long":return n.longValue();case "double":return n.doubleValue();}}return value;}
 public <P,C>C getOrDefault(NamespacedKey key,PersistentDataType<P,C> type,C fallback){C value=get(key,type);return value==null?fallback:value;}
 public boolean has(NamespacedKey key){return values.containsKey(key.toString());}public <P,C>boolean has(NamespacedKey key,PersistentDataType<P,C> type){Object entry=values.get(key.toString());return entry!=null&&kind(type).equals(((Map<?,?>)entry).get("type"));}
 public void remove(NamespacedKey key){if(values.remove(key.toString())!=null)changed();}public boolean isEmpty(){return values.isEmpty();}
 public Set<NamespacedKey> getKeys(){Set<NamespacedKey> keys=new LinkedHashSet<>();for(String key:values.keySet())keys.add(NamespacedKey.fromString(key));return keys;}
 public PersistentDataAdapterContext getAdapterContext(){return DataContainer::new;}
 public void copyTo(PersistentDataContainer other,boolean replace){if(!(other instanceof DataContainer))throw new IllegalArgumentException("Чужой PDC");DataContainer target=(DataContainer)other;Map<String,Object> merged=new LinkedHashMap<>(target.values);for(String key:values.keySet())if(replace||!merged.containsKey(key))merged.put(key,copyEntry(values.get(key)));if(merged.size()>256||size(merged)>16384)throw new IllegalArgumentException("Лимит PDC при копировании");target.values.clear();target.values.putAll(merged);target.changed();}

 private static Object copyEntry(Object value){Map<String,Object> out=new LinkedHashMap<>();for(Map.Entry<?,?> e:((Map<?,?>)value).entrySet())out.put((String)e.getKey(),copy(e.getValue()));return out;}
 public DataContainer clone(){DataContainer copy=new DataContainer();copyTo(copy,true);return copy;}
 public String serialize(){return Yaml.write(values);}
 public static DataContainer parse(String text){DataContainer out=new DataContainer();if(text.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>16384)throw new IllegalArgumentException("Лимит PDC");Map<String,Object> map=Yaml.parse(text);if(map.size()>256)throw new IllegalArgumentException("Лимит ключей PDC");for(Map.Entry<String,Object> e:map.entrySet()){if(NamespacedKey.fromString(e.getKey())==null||!(e.getValue() instanceof Map))throw new IllegalArgumentException("Неверный PDC");Map<?,?> entry=(Map<?,?>)e.getValue();if(entry.size()!=2||!(entry.get("type") instanceof String)||!validValue(entry.get("value"),(String)entry.get("type"),0))throw new IllegalArgumentException("Неверный тип или примитив PDC");out.values.put(e.getKey(),copyEntry(e.getValue()));}return out;}
 @Override public boolean equals(Object other){return other instanceof DataContainer&&Yaml.parse(serialize()).equals(Yaml.parse(((DataContainer)other).serialize()));}@Override public int hashCode(){return Yaml.parse(serialize()).hashCode();}
}
